// Metadata structure for contiguous heap blocks
typedef struct {
    size_t size;         // Data space size
    int is_free;         // Status flag (1 = Free)
} BlockMeta;

// Function to merge adjacent free blocks upon deallocation
void coalesce(BlockMeta* current_block) {
    // Calculate address of the adjacent block immediately following current_block
    BlockMeta* next_block = 
        (BlockMeta*)((char*)current_block + current_block->size + sizeof(BlockMeta));

    // Check if the adjacent block is also free
    if (next_block->is_free) {
        // Merge adjacent memory blocks
        // The size of the coalesced block includes the merged block's data AND metadata
        current_block->size += next_block->size + sizeof(BlockMeta);

        // Logical step: The next_block is now consumed, update free list management
        // free_list_relink(current_block, next_block);
    }
}
